    import gc

    # Background is the most frequent value
    vals = [x for row in grid for x in row]
    if not vals:
        return grid
    bg = Counter(vals).most_common(1)[0][0]

    rows, cols = len(grid), len(grid[0])
    fg_values = set()
    for row in grid:
        for val in row:
            if val != bg:
                fg_values.add(val)

    # Find connected components for each foreground color
    components = {}  # shape_key -> [(color, pixels, h, w), ...]
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and (r, c) not in visited:
                color = grid[r][c]
                pixels = []
                stack = [(r, c)]
                visited.add((r, c))
                while stack:
                    cr, cc = stack.pop()
                    pixels.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if (nr, nc) not in visited and grid[nr][nc] == color:
                                visited.add((nr, nc))
                                stack.append((nr, nc))

                # Normalize
                minr, minc = min(p[0] for p in pixels), min(p[1] for p in pixels)
                mask = [(p[0] - minr, p[1] - minc) for p in pixels]
                mask.sort()
                shape_key = tuple(mask)
                if shape_key not in components:
                    components[shape_key] = []
                components[shape_key].append((color, len(pixels)))

    # Count shape occurrences per color
    color_shape_counts = Counter()
    for shape_key, colors_pixels in components.items():
        for color, _ in colors_pixels:
            color_shape_counts[(shape_key, color)] += 1

    # Find unique occurrences (count == 1)
    unique_occurrences = [k for k, v in color_shape_counts.items() if v == 1]

    if unique_occurrences:
        shape_key, color = unique_occurrences[0]
        for (ck, cp) in components.items():
            if ck == shape_key:
                if len(cp) == 1:
                    return cp[0][0]

    # Fallback: all foreground shapes are the same or return first unique shape
    if components:
        for shape_key, items in components.items():
            if len(items) == 1:
                return items[0][0]

    return grid
